          s += '<ellipse cx="'+ox.toFixed(1)+'" cy="'+(ly+0.4).toFixed(1)+'" rx="1.3" ry="0.4" fill="rgba(40,20,5,0.18)"/>';
          s += '<path d="M'+(ox-0.45)+','+ly+' Q'+(ox+side*_sdR*0.3).toFixed(1)+','+(ly-_sdR*0.4).toFixed(1)+' '+(_sdCx-0.4).toFixed(1)+','+_sdCy.toFixed(1)+' L'+(_sdCx+0.4).toFixed(1)+','+_sdCy.toFixed(1)+' Q'+(ox+side*_sdR*0.3).toFixed(1)+','+(ly-_sdR*0.3).toFixed(1)+' '+(ox+0.45)+','+ly+' Z" fill="rgba(40,20,5,0.6)" opacity="'+(op*0.55).toFixed(2)+'"/>';
          // bodyD = the disc circle path (rough approximation for chimera clip)
          bodyD = 'M'+(_sdCx-_sdR).toFixed(1)+','+_sdCy.toFixed(1)+' A'+_sdR.toFixed(1)+','+_sdR.toFixed(1)+' 0 1,0 '+(_sdCx+_sdR).toFixed(1)+','+_sdCy.toFixed(1)+' A'+_sdR.toFixed(1)+','+_sdR.toFixed(1)+' 0 1,0 '+(_sdCx-_sdR).toFixed(1)+','+_sdCy.toFixed(1)+' Z';
          // Form shadow
          s += '<circle cx="'+(_sdCx+0.5).toFixed(1)+'" cy="'+(_sdCy+0.7).toFixed(1)+'" r="'+_sdR.toFixed(1)+'" fill="rgba(40,20,5,0.30)" opacity="'+(op*0.55).toFixed(2)+'"/>';
          // Translucent disc — papery
          s += '<circle cx="'+_sdCx.toFixed(1)+'" cy="'+_sdCy.toFixed(1)+'" r="'+_sdR.toFixed(1)+'" fill="'+fill+'" opacity="'+Math.max(0.85, op*0.92)+'"/>';
          // Inner translucent core — pale
          s += '<circle cx="'+_sdCx.toFixed(1)+'" cy="'+_sdCy.toFixed(1)+'" r="'+(_sdR*0.78).toFixed(1)+'" fill="#f5ecd6" opacity="'+(op*0.18).toFixed(2)+'"/>';
          // RETICULATE NET — fine vein mesh, the Lunaria signature
          var _sdN = 7;
          for (var _sdv = 0; _sdv < _sdN; _sdv++) {
            var _sda = (_sdv / _sdN) * Math.PI * 2;
            var _sdEx = _sdCx + Math.cos(_sda) * _sdR * 0.92;
            var _sdEy = _sdCy + Math.sin(_sda) * _sdR * 0.92;
            // radial primary (warm dark + cream highlight pair)
            s += '<line x1="'+_sdCx.toFixed(1)+'" y1="'+_sdCy.toFixed(1)+'" x2="'+_sdEx.toFixed(1)+'" y2="'+_sdEy.toFixed(1)+'" stroke="rgba(40,20,5,0.45)" stroke-width="0.18" opacity="'+(op*0.4).toFixed(2)+'" stroke-linecap="round"/>';
            s += '<line x1="'+_sdCx.toFixed(1)+'" y1="'+_sdCy.toFixed(1)+'" x2="'+_sdEx.toFixed(1)+'" y2="'+_sdEy.toFixed(1)+'" stroke="#f5ecd6" stroke-width="0.10" opacity="'+(op*0.30).toFixed(2)+'" stroke-linecap="round" transform="translate(-0.18,-0.12)"/>';
          }
