          // Sharp pickup highlight (silver sheen)
          s += '<path d="M'+(_sdCx-_sdR*0.55).toFixed(1)+','+(_sdCy-_sdR*0.70).toFixed(1)+' A'+_sdR.toFixed(1)+','+_sdR.toFixed(1)+' 0 0,1 '+(_sdCx+_sdR*0.65).toFixed(1)+','+(_sdCy-_sdR*0.55).toFixed(1)+'" fill="none" stroke="#fff8e0" stroke-width="0.75" opacity="0.55" stroke-linecap="round"/>';
          // Pulvinus dot
