          s += '<ellipse cx="'+ox.toFixed(1)+'" cy="'+(ly+0.5).toFixed(1)+'" rx="1.6" ry="0.5" fill="rgba(40,20,5,0.20)"/>';
          bodyD = 'M'+_arSinusX.toFixed(1)+','+_arSinusY.toFixed(1)
             // climb to right lateral lobe (leading-side basal pointer)
