          // Form shadow
          s += '<path d="'+bodyD+'" fill="rgba(40,20,5,0.32)" transform="translate(0.6,0.7)" opacity="'+(op*0.5).toFixed(2)+'"/>';
          s += '<path d="'+bodyD+'" fill="'+fill+'" opacity="'+Math.max(0.92, op)+'"/>';
          // Margin highlight on leading edge
          s += '<path d="M'+_arRLobeX.toFixed(1)+','+_arRLobeY.toFixed(1)+' C'+(ox+side*ls*1.05).toFixed(1)+','+(ly-ls*1.45).toFixed(1)+' '+(ox+side*ls*0.55).toFixed(1)+','+(ly-ls*2.30).toFixed(1)+' '+_arTipX.toFixed(1)+','+_arTipY.toFixed(1)+'" fill="none" stroke="#f5ecd6" stroke-width="0.55" opacity="0.6" stroke-linecap="round"/>';
          // Sinus AO ink-pool — darkest valley behind petiole
          s += '<path d="M'+_arSinusX.toFixed(1)+','+_arSinusY.toFixed(1)+' Q'+(ox+side*ls*0.10).toFixed(1)+','+(ly-ls*0.40).toFixed(1)+' '+_arRLobeX.toFixed(1)+','+_arRLobeY.toFixed(1)+'" fill="none" stroke="rgba(40,20,5,0.55)" stroke-width="0.9" stroke-linecap="round" opacity="'+(op*0.55).toFixed(2)+'"/>';
          s += '<path d="M'+_arSinusX.toFixed(1)+','+_arSinusY.toFixed(1)+' Q'+(ox-side*ls*0.10).toFixed(1)+','+(ly-ls*0.40).toFixed(1)+' '+_arLLobeX.toFixed(1)+','+_arLLobeY.toFixed(1)+'" fill="none" stroke="rgba(40,20,5,0.55)" stroke-width="0.9" stroke-linecap="round" opacity="'+(op*0.55).toFixed(2)+'"/>';
