          s += '<path d="'+_arMidD+'" fill="none" stroke="#f5ecd6" stroke-width="0.32" opacity="0.55" stroke-linecap="round" transform="translate(-0.3,-0.2)"/>';
          // Lobe veins — pointing from midrib base into each basal lobe tip
          s += '<path d="M'+_arSinusX.toFixed(1)+','+_arSinusY.toFixed(1)+' Q'+(ox+side*ls*0.6).toFixed(1)+','+(ly-ls*0.55).toFixed(1)+' '+_arRLobeX.toFixed(1)+','+_arRLobeY.toFixed(1)+'" fill="none" stroke="rgba(40,20,5,0.6)" stroke-width="0.42" opacity="'+(op*0.5).toFixed(2)+'" stroke-linecap="round"/>';
          s += '<path d="M'+_arSinusX.toFixed(1)+','+_arSinusY.toFixed(1)+' Q'+(ox-side*ls*0.5).toFixed(1)+','+(ly-ls*0.55).toFixed(1)+' '+_arLLobeX.toFixed(1)+','+_arLLobeY.toFixed(1)+'" fill="none" stroke="rgba(40,20,5,0.6)" stroke-width="0.42" opacity="'+(op*0.5).toFixed(2)+'" stroke-linecap="round"/>';
