          s += '<ellipse cx="'+(ox+side*ls*0.30).toFixed(1)+'" cy="'+(ly-ls*1.30).toFixed(1)+'" rx="'+(ls*0.35).toFixed(1)+'" ry="'+(ls*0.55).toFixed(1)+'" fill="#f5ecd6" opacity="'+(op*0.10).toFixed(2)+'" transform="rotate(-15 '+(ox+side*ls*0.30).toFixed(1)+' '+(ly-ls*1.30).toFixed(1)+')"/>';
          s += '<ellipse cx="'+(ox+side*ls*0.35).toFixed(1)+'" cy="'+(ly-ls*1.50).toFixed(1)+'" rx="'+(ls*0.14).toFixed(1)+'" ry="'+(ls*0.20).toFixed(1)+'" fill="#fff8e0" opacity="'+(op*0.18).toFixed(2)+'" transform="rotate(-15 '+(ox+side*ls*0.35).toFixed(1)+' '+(ly-ls*1.50).toFixed(1)+')"/>';
          // Tip terminator
          s += '<circle cx="'+_arTipX.toFixed(1)+'" cy="'+_arTipY.toFixed(1)+'" r="0.42" fill="rgba(40,20,5,0.7)"/>';
          // Lobe tip terminator dots
          s += '<circle cx="'+_arRLobeX.toFixed(1)+'" cy="'+_arRLobeY.toFixed(1)+'" r="0.32" fill="rgba(40,20,5,0.6)"/>';
          s += '<circle cx="'+_arLLobeX.toFixed(1)+'" cy="'+_arLLobeY.toFixed(1)+'" r="0.32" fill="rgba(40,20,5,0.6)"/>';
          // Pulvinus dot
          s += '<circle cx="'+ox.toFixed(1)+'" cy="'+ly.toFixed(1)+'" r="0.42" fill="rgba(40,20,5,0.6)"/>';
