             + ' '+(_ssCx-side*_ssR*0.7).toFixed(1)+','+(_ssCy-_ssR*0.3).toFixed(1)
             + ' '+(_ssCx-side*_ssR*0.35).toFixed(1)+','+(_ssCy+_ssR*0.15).toFixed(1)
             + ' C'+(_ssCx-side*_ssR*0.05).toFixed(1)+','+(_ssCy+_ssR*0.5).toFixed(1)
             + ' '+(ox-side*_ssR*0.15).toFixed(1)+','+(ly-_ssR*0.1).toFixed(1)
             + ' '+ox+','+ly+' Z';
          // Body fill
          s += '<path d="'+bodyD+'" fill="'+fill+'" opacity="'+Math.max(0.92, op).toFixed(2)+'"/>';
          // 2nd color iridescence wash (golden tint)
          s += '<ellipse cx="'+(_ssCx+side*_ssR*0.15).toFixed(1)+'" cy="'+(_ssCy+_ssR*0.05).toFixed(1)+'" rx="'+(_ssR*0.55).toFixed(2)+'" ry="'+(_ssR*0.50).toFixed(2)+'" fill="'+_hueShift(_ssCol2, i*29, 12)+'" opacity="'+(op*0.22).toFixed(2)+'"/>';
          // Form shadow on lower-left curl
          s += '<path d="M'+ox+','+ly+' C'+(ox-side*_ssR*0.15).toFixed(1)+','+(ly-_ssR*0.1).toFixed(1)+' '+(_ssCx-side*_ssR*0.05).toFixed(1)+','+(_ssCy+_ssR*0.5).toFixed(1)+' '+(_ssCx-side*_ssR*0.35).toFixed(1)+','+(_ssCy+_ssR*0.15).toFixed(1)+' L'+ox+','+ly+' Z" fill="rgba(40,20,5,0.30)"/>';
          // Whorl strokes — warm dark, decreasing
          s += '<path d="M'+(_ssCx+side*_ssR*0.55).toFixed(1)+','+(_ssCy+_ssR*0.05).toFixed(1)+' A'+(_ssR*0.55).toFixed(2)+','+(_ssR*0.5).toFixed(2)+' 0 0,'+(side>0?1:0)+' '+(_ssCx-side*_ssR*0.25).toFixed(1)+','+(_ssCy-_ssR*0.35).toFixed(1)+'"'
             + ' fill="none" stroke="rgba(40,20,5,0.65)" stroke-width="0.55" opacity="'+(op*0.65).toFixed(2)+'" stroke-linecap="round"/>';
          s += '<path d="M'+(_ssCx-side*_ssR*0.15).toFixed(1)+','+(_ssCy+_ssR*0.1).toFixed(1)+' A'+(_ssR*0.3).toFixed(2)+','+(_ssR*0.28).toFixed(2)+' 0 0,'+(side>0?1:0)+' '+(_ssCx+side*_ssR*0.2).toFixed(1)+','+(_ssCy-_ssR*0.15).toFixed(1)+'"'
             + ' fill="none" stroke="rgba(40,20,5,0.55)" stroke-width="0.45" opacity="'+(op*0.55).toFixed(2)+'" stroke-linecap="round"/>';
          s += '<path d="M'+(_ssCx+side*_ssR*0.12).toFixed(1)+','+(_ssCy+_ssR*0.05).toFixed(1)+' A'+(_ssR*0.15).toFixed(2)+','+(_ssR*0.14).toFixed(2)+' 0 0,'+(side>0?1:0)+' '+(_ssCx-side*_ssR*0.05).toFixed(1)+','+(_ssCy-_ssR*0.05).toFixed(1)+'"'
             + ' fill="none" stroke="rgba(40,20,5,0.50)" stroke-width="0.38" opacity="'+(op*0.50).toFixed(2)+'" stroke-linecap="round"/>';
