          s += '<circle cx="'+_ssCx.toFixed(1)+'" cy="'+_ssCy.toFixed(1)+'" r="'+(_ssR*0.10).toFixed(2)+'" fill="rgba(40,20,5,0.75)"/>';
          s += '<circle cx="'+(_ssCx-_ssR*0.03).toFixed(1)+'" cy="'+(_ssCy-_ssR*0.03).toFixed(1)+'" r="'+(_ssR*0.04).toFixed(2)+'" fill="#fff8e0" opacity="'+(op*0.55).toFixed(2)+'"/>';
