             + ' fill="none" stroke="#f5ecd6" stroke-width="0.65" opacity="'+(op*0.60).toFixed(2)+'" stroke-linecap="round"/>';
          s += '<path d="M'+(_ssCx+side*_ssR*0.4).toFixed(1)+','+(_ssCy-_ssR*0.6).toFixed(1)+' C'+(_ssCx-side*_ssR*0.2).toFixed(1)+','+(_ssCy-_ssR*0.9).toFixed(1)+' '+(_ssCx-side*_ssR*0.7).toFixed(1)+','+(_ssCy-_ssR*0.3).toFixed(1)+' '+(_ssCx-side*_ssR*0.35).toFixed(1)+','+(_ssCy+_ssR*0.15).toFixed(1)+'"'
             + ' fill="none" stroke="#f5ecd6" stroke-width="0.32" opacity="'+(op*0.40).toFixed(2)+'" stroke-linecap="round"/>';
          // Specular flash on shoulder
          s += '<ellipse cx="'+(_ssCx+side*_ssR*0.45).toFixed(1)+'" cy="'+(_ssCy-_ssR*0.30).toFixed(1)+'" rx="'+(_ssR*0.20).toFixed(2)+'" ry="'+(_ssR*0.12).toFixed(2)+'" fill="#fff8e0" opacity="'+(op*0.40).toFixed(2)+'"/>';
