          s += '<path d="'+bodyD+'" fill="rgba(40,20,5,0.18)" transform="translate(0.4,0.3)"/>';
          // Warm dark border
          s += '<path d="'+bodyD+'" fill="none" stroke="rgba(40,20,5,0.55)" stroke-width="0.75" stroke-linejoin="round"/>';
          // Body fill
          s += '<path d="'+bodyD+'" fill="'+fill+'" opacity="'+Math.max(0.92, op)+'"/>';
