            var _nY = _sp1.cy + Math.sin(_diAng) * _diLen * 0.08;
            s += '<path d="M'+_sp1.sx.toFixed(1)+','+_sp1.sy.toFixed(1)+' L'+_nX.toFixed(1)+','+_nY.toFixed(1)+' L'+_sp2.sx.toFixed(1)+','+_sp2.sy.toFixed(1)+'"'
               + ' fill="rgba(40,20,5,0.22)"/>';
