             + ' fill="none" stroke="#fff8e0" stroke-width="0.4" opacity="0.55" stroke-linecap="round"/>';
          // Spike + apex terminator dots
          for (var _dih = 0; _dih < _diSpikes.length; _dih++) {
            s += '<circle cx="'+_diSpikes[_dih].sx.toFixed(1)+'" cy="'+_diSpikes[_dih].sy.toFixed(1)+'" r="0.4" fill="rgba(40,20,5,0.7)"/>';
          }
