          // Specular lozenge upper-third
          s += '<ellipse cx="'+(ox+Math.cos(_diAng)*_diLen*0.32*side+_diPx*_diWid*0.18*side).toFixed(1)+'" cy="'+(ly+Math.sin(_diAng)*_diLen*0.32+_diPy*_diWid*0.18).toFixed(1)+'" rx="'+(_diLen*0.18).toFixed(1)+'" ry="'+(_diWid*0.12).toFixed(1)+'" fill="#fff8e0" opacity="0.22" transform="rotate('+(_diAng*180/Math.PI).toFixed(0)+','+ox+','+ly+')"/>';
