              var _vfpTipY = _vfpY + _vfPy * _vfpS * _vfsd;
              var _vfpD = 'M'+_vfpX.toFixed(1)+','+_vfpY.toFixed(1)
                 + ' C'+(_vfpX+_vfPx*_vfpS*0.4*_vfsd*side).toFixed(1)+','+(_vfpY+_vfPy*_vfpS*0.4*_vfsd-_vfpS*0.15).toFixed(1)
                 + ' '+(_vfpTipX-_vfPx*_vfpS*0.1*_vfsd*side).toFixed(1)+','+(_vfpTipY-_vfPy*_vfpS*0.1*_vfsd-_vfpS*0.04).toFixed(1)
                 + ' '+_vfpTipX.toFixed(1)+','+_vfpTipY.toFixed(1)
