          var _jlMarginY = _jlCy + _jlR * 0.55;
          var _jlBellD = 'M'+(_jlCx-side*_jlR*0.65).toFixed(1)+','+_jlMarginY.toFixed(1)
             + ' C'+(_jlCx-side*_jlR*0.65).toFixed(1)+','+(_jlCy-_jlR*0.4).toFixed(1)+' '+(_jlCx+side*_jlR*0.65).toFixed(1)+','+(_jlCy-_jlR*0.4).toFixed(1)+' '+(_jlCx+side*_jlR*0.65).toFixed(1)+','+_jlMarginY.toFixed(1)+' Z';
          // Form shadow on shaded half
          s += '<ellipse cx="'+(_jlCx+side*_jlR*0.18).toFixed(1)+'" cy="'+(_jlCy+_jlR*0.05).toFixed(1)+'" rx="'+(_jlR*0.55).toFixed(1)+'" ry="'+(_jlR*0.5).toFixed(1)+'" fill="rgba(40,20,5,0.18)"/>';
          // Bioluminescent halo
          s += '<ellipse cx="'+_jlCx.toFixed(1)+'" cy="'+_jlCy.toFixed(1)+'" rx="'+(_jlR*0.9).toFixed(1)+'" ry="'+(_jlR*0.72).toFixed(1)+'" fill="'+fill+'" opacity="'+(op*0.14).toFixed(2)+'"/>';
          // Bell body
          s += '<path d="'+_jlBellD+'" fill="'+fill+'" opacity="'+Math.max(0.85, op)+'"/>';
          // Warm dark margin border
          s += '<path d="'+_jlBellD+'" fill="none" stroke="rgba(40,20,5,0.5)" stroke-width="0.5"/>';
          // Inner luminous core
          s += '<ellipse cx="'+_jlCx.toFixed(1)+'" cy="'+(_jlCy+_jlR*0.05).toFixed(1)+'" rx="'+(_jlR*0.35).toFixed(1)+'" ry="'+(_jlR*0.28).toFixed(1)+'" fill="#fff8e0" opacity="'+(op*0.22).toFixed(2)+'"/>';
