          var _wfTipY = ly - _wfLen;
          bodyD = 'M'+ox+','+ly
             + ' C'+(ox+side*_wfWid*0.95).toFixed(1)+','+(ly+_wfLen*0.02).toFixed(1)+' '+(_wfTipX+side*_wfWid*0.65).toFixed(1)+','+(_wfTipY+_wfLen*0.3).toFixed(1)+' '+_wfTipX.toFixed(1)+','+_wfTipY.toFixed(1)
             + ' C'+(_wfTipX-side*_wfWid*0.3).toFixed(1)+','+(_wfTipY-_wfLen*0.05).toFixed(1)+' '+(ox-side*_wfWid*0.35).toFixed(1)+','+(ly-_wfLen*0.1).toFixed(1)+' '+ox+','+ly+' Z';
