          var glowStartX = fx + Math.cos(rvAng) * rvReach * 0.10;
          var glowStartY = fy + Math.sin(rvAng) * rvReach * 0.10;
          var glowEndX = fx + Math.cos(rvAng) * rvReach * 0.45;
          var glowEndY = fy + Math.sin(rvAng) * rvReach * 0.45;
          s += '<line x1="'+glowStartX.toFixed(1)+'" y1="'+glowStartY.toFixed(1)+'" x2="'+glowEndX.toFixed(1)+'" y2="'+glowEndY.toFixed(1)+'"'
             + ' stroke="'+_rvCream+'" stroke-width="'+(rvPW*0.32).toFixed(2)+'" stroke-linecap="round"'
             + ' opacity="'+(0.32*bloomOp).toFixed(2)+'"/>';
          var rvTermX = fx + Math.cos(rvAng) * rvReach * 0.50;
          var rvTermY = fy + Math.sin(rvAng) * rvReach * 0.50;
          s += '<path d="M'+fx+','+fy
             + ' C'+rvcp1x.toFixed(1)+','+rvcp1y.toFixed(1)+' '+rvcp2x.toFixed(1)+','+rvcp2y.toFixed(1)+' '+rvTermX.toFixed(1)+','+rvTermY.toFixed(1)+'"'
             + ' fill="none" stroke="'+_rvDeep+'" stroke-width="0.22" stroke-linecap="round"'
             + ' opacity="'+(0.20*bloomOp).toFixed(2)+'"/>';
          var mistMidX = rvTipX + Math.cos(rvAng) * rvReach * 0.18 + Math.cos(rvPerp) * rvPW * 0.30;
          var mistMidY = rvTipY + Math.sin(rvAng) * rvReach * 0.18 + Math.sin(rvPerp) * rvPW * 0.30;
          var mistEndX = rvTipX + Math.cos(rvAng) * rvReach * 0.32 - Math.cos(rvPerp) * rvPW * 0.10;
          var mistEndY = rvTipY + Math.sin(rvAng) * rvReach * 0.32 - Math.sin(rvPerp) * rvPW * 0.10;
          s += '<path d="M'+rvTipX.toFixed(1)+','+rvTipY.toFixed(1)
             + ' Q'+mistMidX.toFixed(1)+','+mistMidY.toFixed(1)+' '+mistEndX.toFixed(1)+','+mistEndY.toFixed(1)+'"'
             + ' fill="none" stroke="'+_rvMist+'" stroke-width="0.55" stroke-linecap="round"'
             + ' filter="url(#rvBlur'+uid+')" opacity="'+(0.42*bloomOp).toFixed(2)+'"'
             + ' style="animation:iceShimmer '+(9 + rvi*0.9).toFixed(1)+'s ease-in-out '+(rvi*0.7).toFixed(1)+'s infinite"/>';
          s += '<circle cx="'+rvTipX.toFixed(1)+'" cy="'+rvTipY.toFixed(1)+'" r="'+(rvPW*0.10).toFixed(2)+'"'
