               + ' C'+(pcp3x+fs*0.03).toFixed(1)+','+(pcp3y+fs*0.03).toFixed(1)+' '+(pcp4x+fs*0.03).toFixed(1)+','+(pcp4y+fs*0.03).toFixed(1)+' '+(fx+fs*0.03)+','+(fy+fs*0.03)+' Z"'
               + ' fill="rgba(40,20,5,0.16)" opacity="'+bloomOp+'"/>';

            // ── PETAL BODY — vivid saturated spectral color, full opacity ──
            s += '<path d="M'+fx+','+fy
