            var glowEndX = fx + Math.cos(pAng) * pReach * 0.7;
            var glowEndY = fy + Math.sin(pAng) * pReach * 0.7;
            s += '<path d="M'+glowStartX.toFixed(1)+','+glowStartY.toFixed(1)
               + ' Q'+(fx + Math.cos(pAng)*pReach*0.45 + Math.cos(pPerp)*pW*0.05).toFixed(1)+','+(fy + Math.sin(pAng)*pReach*0.45 + Math.sin(pPerp)*pW*0.05).toFixed(1)
               + ' '+glowEndX.toFixed(1)+','+glowEndY.toFixed(1)+'"'
               + ' fill="none" stroke="'+spec.light+'" stroke-width="'+(pW*0.4)+'" stroke-linecap="round" opacity="'+(0.3*bloomOp).toFixed(2)+'"/>';

