            var midX = fx + Math.cos(pAng) * pReach * 0.65;
            var midY = fy + Math.sin(pAng) * pReach * 0.65;
            s += '<line x1="'+fx+'" y1="'+fy+'" x2="'+midX.toFixed(1)+'" y2="'+midY.toFixed(1)+'"'
               + ' stroke="'+spec.dark+'" stroke-width="0.22" opacity="'+(0.2*bloomOp).toFixed(2)+'"/>';

