              var svEndY = svStartY + Math.sin(pPerp) * svDir * svLen + Math.sin(pAng) * svLen * 0.4;
              s += '<line x1="'+svStartX.toFixed(1)+'" y1="'+svStartY.toFixed(1)+'" x2="'+svEndX.toFixed(1)+'" y2="'+svEndY.toFixed(1)+'"'
