            s += '<path d="M'+fx+','+fy
               + ' C'+pcp4x.toFixed(1)+','+pcp4y.toFixed(1)+' '+pcp3x.toFixed(1)+','+pcp3y.toFixed(1)+' '+pTipX.toFixed(1)+','+pTipY.toFixed(1)+'"'
               + ' fill="none" stroke="'+spec.shadow.replace('0.15','0.2')+'" stroke-width="0.3" opacity="'+bloomOp+'"/>';

            // ── TIP GLOW — each petal tip gets a soft bright halo in its color ──
            s += '<circle cx="'+pTipX.toFixed(1)+'" cy="'+pTipY.toFixed(1)+'" r="'+(pW*0.2)+'"'
               + ' fill="'+spec.light+'" opacity="'+(0.2*bloomOp).toFixed(2)+'"/>';

