            // Faint arc of the NEXT color bleeding into this petal's edge
            var nextSpec = _prSpec[(pi + 1) % 6];
            var blendX = fx + Math.cos(pAng + Math.PI/12) * pReach * 0.5; // between this and next petal
            var blendY = fy + Math.sin(pAng + Math.PI/12) * pReach * 0.5;
            s += '<ellipse cx="'+blendX.toFixed(1)+'" cy="'+blendY.toFixed(1)+'" rx="'+(pW*0.15)+'" ry="'+(pReach*0.1)+'"'
               + ' fill="'+nextSpec.fill+'" opacity="'+(0.08*bloomOp).toFixed(2)+'"'
