            s += '<circle cx="'+fp.x.toFixed(1)+'" cy="'+fp.y.toFixed(1)+'" r="'+fpR+'"'
               + ' fill="'+_frostW+'" opacity="'+(0.3*bloomOp).toFixed(2)+'">';
