            s += '<animateTransform attributeName="transform" type="translate"'
               + ' values="0,0;'+(Math.sin(fpi*1.8)*0.4).toFixed(1)+','+(Math.cos(fpi*2.3)*0.3).toFixed(1)+';0,0"'
               + ' dur="'+(4 + fpi*0.7).toFixed(1)+'s" repeatCount="indefinite"/>';
            s += '</circle>';
