            s += '<line x1="'+(fp.x - fpR*1.5).toFixed(1)+'" y1="'+fp.y.toFixed(1)+'" x2="'+(fp.x + fpR*1.5).toFixed(1)+'" y2="'+fp.y.toFixed(1)+'"'
               + ' stroke="'+_frostW+'" stroke-width="0.1" opacity="'+(0.2*bloomOp).toFixed(2)+'"/>';
            s += '<line x1="'+fp.x.toFixed(1)+'" y1="'+(fp.y - fpR*1.5).toFixed(1)+'" x2="'+fp.x.toFixed(1)+'" y2="'+(fp.y + fpR*1.5).toFixed(1)+'"'
               + ' stroke="'+_frostW+'" stroke-width="0.1" opacity="'+(0.2*bloomOp).toFixed(2)+'"/>';
            // POLISH: frost particle glow halo (E4 — 2x radius, 0.25 opacity)
            s += '<circle cx="'+fp.x.toFixed(1)+'" cy="'+fp.y.toFixed(1)+'" r="'+(fpR*2.2).toFixed(2)+'"'
               + ' fill="#cfe6f5" opacity="'+(0.22*bloomOp).toFixed(2)+'"/>';
