            var jag1X = fX - fW * 0.6;
            var jag1Y = fy - fH * 0.25;
            var jag2X = fX - fW * 0.3 + Math.sin(fi * 5.1) * fW * 0.4;
            var jag2Y = fy - fH * 0.5;
            var jag3X = fX - fW * 0.15 + Math.sin(fi * 3.8) * fW * 0.2;
            var jag3Y = fy - fH * 0.75;
            // Right edge: mirrored but different jags
            var jag4X = fX + fW * 0.2 + Math.sin(fi * 4.3) * fW * 0.25;
            var jag4Y = fy - fH * 0.7;
            var jag5X = fX + fW * 0.4 + Math.sin(fi * 2.7) * fW * 0.3;
            var jag5Y = fy - fH * 0.4;
            var jag6X = fX + fW * 0.55;
            var jag6Y = fy - fH * 0.15;

            // Color: center petals are brighter, edge petals are redder
            var centerFrac = 1 - Math.abs(fi - (_flPetals-1)/2) / ((_flPetals-1)/2);
