               + ' L'+jag2X.toFixed(1)+','+jag2Y.toFixed(1)
               + ' L'+jag3X.toFixed(1)+','+jag3Y.toFixed(1)
               + ' Q'+(fTipX - fW*0.1).toFixed(1)+','+(fTipY + fH*0.05).toFixed(1)+' '+fTipX.toFixed(1)+','+fTipY.toFixed(1)  // sharp tip with tiny curve
               + ' Q'+(fTipX + fW*0.1).toFixed(1)+','+(fTipY + fH*0.05).toFixed(1)+' '+jag4X.toFixed(1)+','+jag4Y.toFixed(1)
               + ' L'+jag5X.toFixed(1)+','+jag5Y.toFixed(1)
