            s += '<path d="M'+fX.toFixed(1)+','+fy
               + ' L'+jag1X.toFixed(1)+','+jag1Y.toFixed(1)
               + ' L'+jag2X.toFixed(1)+','+jag2Y.toFixed(1)
               + ' L'+jag3X.toFixed(1)+','+jag3Y.toFixed(1)+'"'
               + ' fill="none" stroke="rgba(255,240,180,0.2)" stroke-width="0.3" stroke-linejoin="round" opacity="'+bloomOp+'"/>';
