          s += '<ellipse cx="'+fx+'" cy="'+(fy + fs*0.02)+'" rx="'+(_flBaseR*0.45)+'" ry="'+(_flBaseR*0.22)+'"'
             + ' fill="'+_flHot+'" opacity="'+(0.7*bloomOp)+'"/>';
          // White-hot center — cream diffuse (A4)
          s += '<ellipse cx="'+fx+'" cy="'+fy+'" rx="'+(_flBaseR*0.25)+'" ry="'+(_flBaseR*0.12)+'"'
             + ' fill="#f5ecd6" opacity="'+(0.85*bloomOp)+'"/>';
          // POLISH: small sharp pure-white specular pickup ON TOP of cream diffuse (A3 dual-specular)
          s += '<ellipse cx="'+(fx - _flBaseR*0.06)+'" cy="'+(fy - _flBaseR*0.04)+'" rx="'+(_flBaseR*0.10)+'" ry="'+(_flBaseR*0.05)+'"'
