            var wcp1x = fx + Math.cos(wAng) * wReach * 0.25 + Math.cos(wPerp) * wW * 0.6;
            var wcp1y = fy + Math.sin(wAng) * wReach * 0.25 + Math.sin(wPerp) * wW * 0.6;
            var wcp2x = wTipX + Math.cos(wPerp) * wW * 0.2;
            var wcp2y = wTipY + Math.sin(wPerp) * wW * 0.2;
            var wcp3x = wTipX - Math.cos(wPerp) * wW * 0.2;
            var wcp3y = wTipY - Math.sin(wPerp) * wW * 0.2;
            var wcp4x = fx + Math.cos(wAng) * wReach * 0.25 - Math.cos(wPerp) * wW * 0.6;
            var wcp4y = fy + Math.sin(wAng) * wReach * 0.25 - Math.sin(wPerp) * wW * 0.6;

            // Wing petal body
            s += '<path d="M'+fx+','+fy
               + ' C'+wcp1x.toFixed(1)+','+wcp1y.toFixed(1)+' '+wcp2x.toFixed(1)+','+wcp2y.toFixed(1)+' '+wTipX.toFixed(1)+','+wTipY.toFixed(1)
               + ' C'+wcp3x.toFixed(1)+','+wcp3y.toFixed(1)+' '+wcp4x.toFixed(1)+','+wcp4y.toFixed(1)+' '+fx+','+fy+' Z"'
               + ' fill="'+fc+'" opacity="'+(0.92*bloomOp)+'" stroke="rgba(40,20,5,0.08)" stroke-width="0.12"/>';

            // Wing midrib
            var wmX = fx + Math.cos(wAng) * wReach * 0.5;
            var wmY = fy + Math.sin(wAng) * wReach * 0.5;
            s += '<line x1="'+fx+'" y1="'+fy+'" x2="'+wmX.toFixed(1)+'" y2="'+wmY.toFixed(1)+'"'
               + ' stroke="rgba(40,20,5,0.08)" stroke-width="0.15" opacity="'+bloomOp+'"/>';

