            var scp2y = sTipY + Math.sin(sPerp) * sW * 0.25;
            var scp3x = sTipX - Math.cos(sPerp) * sW * 0.25;
            var scp3y = sTipY - Math.sin(sPerp) * sW * 0.25;
            var scp4x = fx + sd.xOff * _viR + Math.cos(sAng) * sReach * 0.25 - Math.cos(sPerp) * sW * 0.6;
            var scp4y = fy + Math.sin(sAng) * sReach * 0.25 - Math.sin(sPerp) * sW * 0.6;

            // Standard body — slightly darker than wings/lip for depth
            s += '<path d="M'+fx+','+fy
               + ' C'+scp1x.toFixed(1)+','+scp1y.toFixed(1)+' '+scp2x.toFixed(1)+','+scp2y.toFixed(1)+' '+sTipX.toFixed(1)+','+sTipY.toFixed(1)
               + ' C'+scp3x.toFixed(1)+','+scp3y.toFixed(1)+' '+scp4x.toFixed(1)+','+scp4y.toFixed(1)+' '+fx+','+fy+' Z"'
               + ' fill="'+fc+'" opacity="'+(0.96*bloomOp)+'" stroke="rgba(40,20,5,0.10)" stroke-width="0.15"/>';

            // Standard dark velvet overlay — upper petals often darker in violas
            s += '<path d="M'+fx+','+fy
               + ' C'+scp1x.toFixed(1)+','+scp1y.toFixed(1)+' '+scp2x.toFixed(1)+','+scp2y.toFixed(1)+' '+sTipX.toFixed(1)+','+sTipY.toFixed(1)
               + ' C'+scp3x.toFixed(1)+','+scp3y.toFixed(1)+' '+scp4x.toFixed(1)+','+scp4y.toFixed(1)+' '+fx+','+fy+' Z"'
               + ' fill="rgba(40,20,5,0.13)" opacity="'+bloomOp+'"/>';

            // Standard midrib
            var smX = fx + sd.xOff * _viR + Math.cos(sAng) * sReach * 0.5;
            var smY = fy + Math.sin(sAng) * sReach * 0.5;
            s += '<line x1="'+fx+'" y1="'+fy+'" x2="'+smX.toFixed(1)+'" y2="'+smY.toFixed(1)+'"'
               + ' stroke="rgba(40,20,5,0.10)" stroke-width="0.15" opacity="'+bloomOp+'"/>';

            // Standard highlight — upper edge
            s += '<path d="M'+fx+','+fy
               + ' C'+scp1x.toFixed(1)+','+scp1y.toFixed(1)+' '+scp2x.toFixed(1)+','+scp2y.toFixed(1)+' '+sTipX.toFixed(1)+','+sTipY.toFixed(1)+'"'
               + ' fill="none" stroke="#fff8e0" stroke-width="0.35" opacity="'+bloomOp+'"/>';

            // POLISH: warm cream specular patch on lit side (A2 cool→warm hue + A3 diffuse)
            var _viSpecX = fx + sd.xOff * _viR + Math.cos(sAng) * sReach * 0.50 + Math.cos(sPerp) * sW * 0.30;
