            s += '<ellipse cx="'+_viSpecX.toFixed(1)+'" cy="'+_viSpecY.toFixed(1)+'" rx="'+(sW*0.22).toFixed(2)+'" ry="'+(sReach*0.16).toFixed(2)+'"'
               + ' fill="#f5ecd6" opacity="'+(0.30*bloomOp).toFixed(2)+'"'
