            var bcp1y = cy + Math.sin(bAng) * bReach * 0.3 + Math.sin(bPerp) * bW * 0.55;
            var bcp2x = cx + Math.cos(bAng) * bReach * 0.3 - Math.cos(bPerp) * bW * 0.55;
            var bcp2y = cy + Math.sin(bAng) * bReach * 0.3 - Math.sin(bPerp) * bW * 0.55;

