              var wcp1y = cy + Math.sin(wAng) * wReach * 0.35 + Math.sin(wPerp) * wW * 0.5;
              var wcp2x = cx + Math.cos(wAng) * wReach * 0.35 - Math.cos(wPerp) * wW * 0.5;
              var wcp2y = cy + Math.sin(wAng) * wReach * 0.35 - Math.sin(wPerp) * wW * 0.5;

              s += '<path d="M'+cx.toFixed(1)+','+cy.toFixed(1)
                 + ' C'+wcp1x.toFixed(1)+','+wcp1y.toFixed(1)+' '+(wTipX+Math.cos(wPerp)*wW*0.1).toFixed(1)+','+(wTipY+Math.sin(wPerp)*wW*0.1).toFixed(1)+' '+wTipX.toFixed(1)+','+wTipY.toFixed(1)
