            s += '<path d="M'+fx+','+fy
               + ' C'+ocp1x.toFixed(1)+','+ocp1y.toFixed(1)+' '+ocp2x.toFixed(1)+','+ocp2y.toFixed(1)+' '+oTipX.toFixed(1)+','+oTipY.toFixed(1)
               + ' C'+ocp3x.toFixed(1)+','+ocp3y.toFixed(1)+' '+ocp4x.toFixed(1)+','+ocp4y.toFixed(1)+' '+fx+','+fy+' Z"'
               + ' fill="#F0D0D8" opacity="'+(0.88*bloomOp)+'" stroke="rgba(180,120,130,0.1)" stroke-width="0.18"/>';

