            s += '<path d="M'+fx+','+fy
               + ' C'+icp1x.toFixed(1)+','+icp1y.toFixed(1)+' '+icp2x.toFixed(1)+','+icp2y.toFixed(1)+' '+iTipX.toFixed(1)+','+iTipY.toFixed(1)
               + ' C'+icp3x.toFixed(1)+','+icp3y.toFixed(1)+' '+icp4x.toFixed(1)+','+icp4y.toFixed(1)+' '+fx+','+fy+' Z"'
               + ' fill="#E8A8B8" opacity="'+(0.92*bloomOp)+'" stroke="rgba(160,80,100,0.1)" stroke-width="0.15"/>';

