               + ' stroke="rgba(160,80,100,0.08)" stroke-width="0.18" opacity="'+bloomOp+'"/>';

            // White tip wash — lotus petals lighten at the edges
            s += '<ellipse cx="'+iTipX.toFixed(1)+'" cy="'+iTipY.toFixed(1)+'" rx="'+(iPW*0.2)+'" ry="'+(iReach*0.08)+'"'
               + ' fill="#fff8e0" opacity="'+bloomOp+'"'
               + ' transform="rotate('+(iAng*180/Math.PI).toFixed(0)+','+iTipX.toFixed(1)+','+iTipY.toFixed(1)+')"/>';

