            var notchL = tipX + Math.cos(perpP) * _bsPW * 0.08;
            var notchR = tipX - Math.cos(perpP) * _bsPW * 0.08;
            var notchLy = tipY + Math.sin(perpP) * _bsPW * 0.08;
            var notchRy = tipY - Math.sin(perpP) * _bsPW * 0.08;
