          // Secondary inner ridge — gives each plate a raised center feel
          var _yIn = (_y1 + _y2) * 0.5;
          var _xIn = Math.sqrt(Math.max(0, _pbR * _pbR - _yIn * _yIn));
          s += '<path d="M'+(-_xIn*0.7).toFixed(1)+','+_yIn.toFixed(1)+' Q0,'+(_yIn-0.3).toFixed(1)+' '+(_xIn*0.7).toFixed(1)+','+_yIn.toFixed(1)+'" fill="none" stroke="rgba(180,180,195,0.08)" stroke-width="0.15"/>';
          // Pitting texture — 2-3 tiny dimples per plate
