        s += '<ellipse cx="54" cy="26.5" rx="0.5" ry="0.4" fill="rgba(230,250,120,0.5)"><animate attributeName="opacity" values="0.5;0.9;0.1;0;0.7;1;0.3;0.5" dur="3.2s" repeatCount="indefinite"/></ellipse>';
